mapper.select:
select vm.*, pd.sku_no as skuNo,pd.name as productName, wh.name as warehouseName, vw.code as virtualWarehouseCode,vw.name as virtualWarehouseName from (select vtf.sku_id as skuId, vtf.warehouse_id as warehouseId, vtf.virtual_warehouse_id as virtualWarehouseId, vtfd.bill_date as date, vtf.transaction_no as transactionNo, vtfd.trade_time as tradeTime, vtf.source_type as sourceType, vtf.source_code as sourceCode, vtf.dict_inventory_status as dictInventoryStatus, vtfd.qty, case when vtfd.qty > 0 then '入库' else '出库' end as operateTypeName, vid.batch_no as batchNo, vtfd.cur_inventory_qty as waitBatchQty, vid.last_outstock_date, vtfd.update_time as updateTime, vid.bill_date from virtual_trans_flow_detail vtfd inner join virtual_trans_flow vtf on vtfd.virtual_trans_flow_id = vtf.id and vtf.is_deleted = false inner join virtual_inventory_detail vid on vtfd.virtual_inventory_detail_id = vid.id and vid.is_deleted = false where vtfd.is_deleted = false union all select vid.sku_id as skuId, vid.warehouse_id as warehouseId, vid.virtual_warehouse_id as virtualWarehouseId, vidh.date as date, '' as transactionNo, vid.trade_time as tradeTime, '' as sourceType, '' as sourceCode, '' as dictInventoryStatus, null as qty, '转结' as operateTypeName, vid.batch_no as batchNo, vidh.qty as waitBatchQty, vid.last_outstock_date as last_outstock_date, vidh.update_time as updateTime, vid.bill_date from virtual_inventory_detail_his vidh left join virtual_inventory_detail vid on vidh.virtual_inventory_detail_id = vid.id and vid.is_deleted = false where vidh.is_deleted = false and vid.qty != 0) vm left join product_detail pd on vm.skuId = pd.id and pd.is_deleted = false left join warehouse wh on vm.warehouseId = wh.id and wh.is_deleted = false left join virtual_warehouse vw on vm.virtualWarehouseId = vw.id and vw.is_deleted = false
${params.sqlMap.default}
order by
${item.field} ${item.sort}
tradeTime desc,batchNo desc,case when operateTypeName = '转结' then 2 else 1 end,date asc

select
    distinct vtfd.virtual_inventory_detail_id
from virtual_trans_flow_detail vtfd
inner join virtual_trans_flow  vtf  on vtfd.virtual_trans_flow_id = vtf.id and vtf.is_deleted = false
where vtfd.is_deleted = false

    and vtf.sku_id = #{skuId}


    and vtf.virtual_inventory_id = #{virtualInventoryId}


    and vtf.virtual_warehouse_id = #{virtualWarehouseId}


    and vtf.warehouse_id = #{warehouseId}


    and vtfd.virtual_inventory_detail_id in (select virtual_inventory_detail_id from virtual_inventory_detail_temp)

select

from virtual_trans_flow_detail vtfd
left join virtual_trans_flow vtf on vtfd.virtual_trans_flow_id = vtf.id and vtf.is_deleted = false
where vtfd.is_deleted = false and  0 > vtfd.qty 
and vtf.sku_id = #{paramDTO.skuId} and vtf.warehouse_id = #{paramDTO.warehouseId}
and vtf.virtual_warehouse_id = #{paramDTO.virtualWarehouseId} and  vtfd.trade_time >= #{paramDTO.tradeTime}
